const auto began=std::chrono::steady_clock::now();
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
uint64_t elapsed(){return uint64_t(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-began).count());}
uint64_t rss(){rusage r{};check(::getrusage(RUSAGE_SELF,&r)==0,"resource query");
#ifdef __APPLE__
 return uint64_t(r.ru_maxrss)/1024;
#else
 return uint64_t(r.ru_maxrss);
#endif
}
void checkpoint(){check(elapsed()<60000&&rss()<=131072,"bootstrap CAS test resource bound");}
std::string read(const fs::path& p,size_t limit=32*1024*1024){std::ifstream in(p,std::ios::binary);check(bool(in),"public/owned file read");std::string s((std::istreambuf_iterator<char>(in)),{});check(s.size()<=limit,"public/owned file bound");return s;}
Bytes bytes_of(const std::string& s){return Bytes(s.begin(),s.end());}
Json token_json(const ForkCheckpointToken& t){return {{"sequence",quantity(Int(std::to_string(t.sequence)))},{"digest",hex(t.digest)}};}
ForkCheckpointToken token_from(const Json& j){return {u64(quantity(j.at("sequence"))),unhex(j.at("digest").get<std::string>())};}
void save(const fs::path& p,const Json& j){const auto s=j.dump();int fd=::open(p.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW,0600);check(fd>=0,"exclusive control file");size_t at=0;while(at<s.size()){const auto n=::write(fd,s.data()+at,s.size()-at);if(n<0&&errno==EINTR)continue;check(n>0,"control write");at+=size_t(n);}check(::fsync(fd)==0&&::close(fd)==0,"control fsync");}
struct Temp{fs::path path;Temp(){auto pattern=(fs::temp_directory_path()/"nano-bootstrap-cas-XXXXXX").string();check(::mkdtemp(pattern.data()),"owned temporary fixture");path=fs::canonical(pattern);}~Temp(){std::error_code e;fs::remove_all(path,e);}};
