size_t witness_limit(const Fixture& f){return 2048+8*f.limits.envelope_bytes;}
Bytes archive_root(const Fixture& f){const auto root=consensus_beacon_header_root(f.proof.header());return {root.begin(),root.end()};}
std::string archive_key(const Fixture& f){return "checkpoint-archive/v1/"+hex(archive_root(f));}
std::string index_key(const Fixture& f){return "checkpoint-archive-slot/v1/"+hex(bytes(Int(1),8))+"/"+hex(archive_root(f));}
using Rows=std::map<std::string,std::string>;
Rows logical(const fs::path& path){rocksdb::Options options;options.create_if_missing=false;rocksdb::DB* raw=nullptr;check(rocksdb::DB::OpenForReadOnly(options,path.string(),&raw).ok(),"owned logical read-only open");std::unique_ptr<rocksdb::DB> db(raw);std::unique_ptr<rocksdb::Iterator> it(db->NewIterator(rocksdb::ReadOptions{}));Rows rows;size_t total=0;for(it->SeekToFirst();it->Valid();it->Next()){checkpoint();auto k=it->key().ToString(),v=it->value().ToString();total+=k.size()+v.size();check(rows.size()<1024&&total<=32*1024*1024,"owned logical inventory bound");check(rows.emplace(std::move(k),std::move(v)).second,"duplicate logical key");}check(it->status().ok(),"complete logical inventory");return rows;}
Rows hashes(const fs::path& root){Rows out;size_t total=0;for(const auto& row:fs::recursive_directory_iterator(root)){checkpoint();check(!row.is_symlink(),"temporary DB symlink");if(!row.is_regular_file())continue;const auto s=read(row.path());total+=s.size();check(out.size()<512&&total<=64*1024*1024,"temporary file inventory bound");out.emplace(fs::relative(row.path(),root).string(),hex(sha256(bytes_of(s))));}return out;}
void mutate(const fs::path& path,const std::function<void(rocksdb::DB&)>& action){rocksdb::Options o;o.create_if_missing=false;rocksdb::DB* raw=nullptr;check(rocksdb::DB::Open(o,path.string(),&raw).ok(),"owned adverse DB open");std::unique_ptr<rocksdb::DB> db(raw);action(*db);}
struct Pair{
 const Fixture& f;fs::path root;std::unique_ptr<Blockchain> owner;std::unique_ptr<ChainStore> witness;std::unique_ptr<CapellaDurableReactor> reactor;
 Pair(const Fixture& x,const fs::path& p,bool fresh,bool signed_initial=false):f(x),root(p){
  owner=std::make_unique<Blockchain>(root/"primary",f.genesis);witness=std::make_unique<ChainStore>(root/"witness");
  if(fresh&&signed_initial)reactor=std::make_unique<CapellaDurableReactor>(*owner,f.rules,f.limits,f.initial,f.proof,*witness,checkpoint);
  else if(fresh)reactor=std::make_unique<CapellaDurableReactor>(*owner,f.rules,f.limits,f.initial,checkpoint,witness.get());
  else reactor=std::make_unique<CapellaDurableReactor>(*owner,f.rules,f.limits,*witness,checkpoint);
 }
 void close(){reactor.reset();owner.reset();witness.reset();}
 ForkCheckpointRecord primary()const{const auto p=owner->store().fork_checkpoint(f.genesis.chain_id,f.genesis.block.header.hash(),f.limits.envelope_bytes);check(bool(p),"owned primary checkpoint");return *p;}
 ForkCheckpointRecord witnessed()const{const auto p=witness->fork_checkpoint(f.genesis.chain_id,f.genesis.block.header.hash(),witness_limit(f));check(bool(p),"owned witness checkpoint");return *p;}
 CapellaBootstrapArchivePlan plan()const{return reactor->prepare_bootstrap_archive(f.proof,primary().token,witnessed().token,checkpoint);}
};
template<class Action>void no_io(Pair& p,Action&& action,const char* reason){const auto before_primary=logical(p.root/"primary"),before_witness=logical(p.root/"witness");const auto before_files=hashes(p.root);refused(std::forward<Action>(action),reason);check(hashes(p.root)==before_files,"refusal wrote physical DB bytes");check(logical(p.root/"primary")==before_primary&&logical(p.root/"witness")==before_witness,"refusal changed complete logical stores");}
void verify_supplement(const Fixture& f,const Rows& before,const Rows& after,const ForkCheckpointToken& next){auto expected=before;expected["fork-checkpoint/v1/token"]=token_json(next).dump();expected[archive_key(f)]=Json{{"slot","0x1"},{"payload",hex(f.wire)},{"digest",hex(sha256(f.wire))}}.dump();expected[index_key(f)]="";check(after==expected,"archive-only supplement changed unrelated primary content");}
void emit(const char* scenario,const Json& extra=Json::object()){auto j=extra;j["scenario"]=scenario;j["result"]="PASS";j["productionQualified"]=false;std::cout<<j.dump()<<std::endl;}
